+// Stock de un artículo en cada almacén donde tuvo movimientos, ordenado por código de almacén.
+export function stockPorAlmacen(movimientos, articulo) {
+  const almacenes = [...new Set(movimientos.filter((m) => m.articulo === articulo).map((m) => m.almacen))].sort();
+  return almacenes.map((almacen) => ({ almacen, stock: stock(movimientos, articulo, almacen) }));
+}
